contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint donateAmount) public payable {
        require(address(this).balance >= depositAmount + donateAmount, "insufficient balance");
        // Give c some Ether without creating credit for this test contract.
        if (donateAmount > 0) {
            (bool ok, ) = address(c).call{value: donateAmount}("");
            require(ok, "donation failed");
        }
        // Create credit for this test contract.
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        uint balanceBefore = address(c).balance;
        uint myCreditBefore = c.credit(address(this));
        uint myBalanceBefore = address(this).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = address(c).balance;
        uint myCreditAfter = c.credit(address(this));
        uint myBalanceAfter = address(this).balance;

        assert(
            (!reverted && myCreditBefore == 0) ?
                (balanceAfter == balanceBefore && myCreditAfter == 0 && myBalanceAfter == myBalanceBefore) :
                (!reverted ?
                    (balanceAfter == balanceBefore - myCreditBefore && myCreditAfter == 0 && myBalanceAfter == myBalanceBefore + myCreditBefore) :
                    (balanceAfter == balanceBefore && myCreditAfter == myCreditBefore && myBalanceAfter == myBalanceBefore))
        );
    }

    receive() external payable {}
}

